UPDATE public.admin_recipes SET title_uz = COALESCE(title_uz, 'Buffalo uslubidagi gulkaram'), description_uz = COALESCE(description_uz, 'Amerikaning mashhur "Buffalo Wings" (tovuq qanotchalari) taomiga 100% vegetarian va foydali muqobil.

