UPDATE public.admin_recipes SET title_uz = COALESCE(title_uz, 'Andalusiya shabadasi — ispancha gaspacho'), description_uz = COALESCE(description_uz, 'Ispaniyaning janubidan kelib chiqqan, pishirmasdan tayyorlanadigan salqin, xom va vitaminlarga boy pomidorli sho‘rva.

