UPDATE public.admin_recipes SET title_uz = COALESCE(title_uz, 'Gold Mac & Cheese (2 yosh+)'), description_uz = COALESCE(description_uz, 'Bolalar eng yaxshi ko‘radigan pishloqli makaronning ichiga sabzavotlar yashirilgan juda foydali turi.

