UPDATE public.admin_recipes SET title_uz = COALESCE(title_uz, 'Yulduzli tun sho‘rvasi (3 yosh+)'), description_uz = COALESCE(description_uz, 'Sho‘rva ichishni yoqtirmaydigan bolalar uchun ichida yulduzchalar suzib yuradigan, suyak bulyonidan tayyorlangan mazali taom.

