UPDATE public.admin_recipes SET title_uz = COALESCE(title_uz, 'Matchali qulupnay buluti'), description_uz = COALESCE(description_uz, 'Ijtimoiy tarmoqlardagi eng urfdagi ichimlik. Terini oziqlantiruvchi antioksidantlar manbai.'), category_uz = COALESCE(category_uz, 'Sog‘lom ichimliklar'), tags_uz = COALESCE(tags_uz, ARRAY['umumiy']::text[]), ingredients_uz = COALESCE(ingredients_uz, '["1 choy qoshiq matcha kukuni (iliq suvda eritilgan), 4-5 dona yangi qulupnay (pyure holiga keltirilgan), 1 stakan bodom suti, muz."]'::jsonb), instructions_uz = COALESCE(instructions_uz, '["Stakan tubiga qulupnay pyuresini soling, ustidan muz va sut qo‘shing. Oxirida eritilgan yashil matchani sekin quying, shunda ranglar qatlam-qatlam (pastda pushti, tepada yashil) bo‘lib qoladi."]'::jsonb) WHERE id = '40f5ac74-8479-42d8-bab7-5b56e15de9ae';
UPDATE public.admin_recipes SET title_uz = COALESCE(title_uz, 'Bodomli pankeyk va chia jemi'), description_uz = COALESCE(description_uz, 'Oddiy undan tayyorlanadigan pankeyklarning glyutensiz va shakarsiz "sog‘lom hayot" muqobili.

