UPDATE public.admin_recipes SET title_uz = COALESCE(title_uz, 'Peru sevichesi'), description_uz = COALESCE(description_uz, 'Lotin Amerikasining baliq olovsiz, faqat sitrus kislotasi yordamida "pishadigan" tetiklantiruvchi va oqsilga boy taomi.

