UPDATE public.admin_recipes SET title_uz = COALESCE(title_uz, 'Skandinaviya Smørrebrød'), description_uz = COALESCE(description_uz, 'Daniya va Norvegiyaga xos, to‘q rangli javdar noni ustida tayyorlanadigan ochiq sendvich san’ati.

