UPDATE public.admin_recipes SET title_uz = COALESCE(title_uz, 'Kinoali tabbule (Livan oshxonasi)'), description_uz = COALESCE(description_uz, 'An’anaviy bulg‘ur o‘rniga glyutensiz va oqsilga boyroq kinoa ishlatiladigan mashhur Yaqin Sharq salati.

