UPDATE public.admin_recipes SET title_uz = COALESCE(title_uz, 'Hindcha yasmiq pyuresi'), description_uz = COALESCE(description_uz, 'Vegetarianlarning sevimli taomi — ziravorlar kuchi bilan tanani ichdan isitadigan tillarang hindcha dimlama.

