UPDATE public.admin_recipes SET title_uz = COALESCE(title_uz, 'Nemischa kartoshka salati'), description_uz = COALESCE(description_uz, 'Og‘ir, mayonezli salatlar o‘rnini bosadigan, xantal va sirkali ajoyib yengil nemis salati.

