UPDATE public.admin_recipes SET title_uz = COALESCE(title_uz, 'Shrek''s Mac & Cheese (3 yosh+)'), description_uz = COALESCE(description_uz, 'Chiroyli yashil rangi bilan e’tiborni tortadigan, ichiga ismaloq yashirilgan pishloqli makaron.

