UPDATE public.admin_recipes SET title_uz = COALESCE(title_uz, 'Oltin yog‘du tonigi'), description_uz = COALESCE(description_uz, 'Tanadagi yallig‘lanishni kamaytiradigan va kasalliklardan himoya qiladigan ertalabki tonik.

