UPDATE public.admin_recipes SET title_uz = COALESCE(title_uz, 'Rang-barang sixchalar(5 yaş+)'), description_uz = COALESCE(description_uz, 'Sabzavot va go‘shtni birga, rangli o‘yin kabi taqdim etadigan sixchalar.

