UPDATE public.admin_recipes SET title_uz = COALESCE(title_uz, 'Pesto sousli kabachki spagettisi'), description_uz = COALESCE(description_uz, 'Xamirli taomdan bahramand bo‘lish hissini beradigan, ammo mutlaqo semirtirmaydigan ajoyib pasta.

