UPDATE public.admin_recipes SET title_uz = COALESCE(title_uz, 'Oltin yasmiq va zanjabil sho‘rvasi'), description_uz = COALESCE(description_uz, 'Moddalar almashinuvini faollashtiradigan, ichdan isitadigan qishki tushlik.

