UPDATE public.admin_recipes SET title_uz = COALESCE(title_uz, 'Shirin kartoshka va loviya'), description_uz = COALESCE(description_uz, 'PMS (hayz oldi) davrida shirinlikka bo‘lgan ehtiyoj va kayfiyat o‘zgarishlarini me’yorlashtirishga yordam beradigan retsept.

