UPDATE public.admin_recipes SET title_uz = COALESCE(title_uz, 'Kichkina ayiqcha pyuresi(1 yosh+)'), description_uz = COALESCE(description_uz, 'Go‘shtni chaynashga qiynaladigan bolalar uchun og‘izda eriydigan, shirali qishki taom.

