UPDATE public.admin_recipes SET title_uz = COALESCE(title_uz, 'Brokkoli va mol go‘shti sotesi'), description_uz = COALESCE(description_uz, 'Mashhur Osiyo (Xitoy) oshxonasining butun dunyoda seviladigan eng foydali klassik taomlaridan biri.

