UPDATE public.admin_recipes SET title_uz = COALESCE(title_uz, 'Zig‘ir va bodom unidan kreker'), description_uz = COALESCE(description_uz, 'Do‘konda sotiladigan zararli chipslar o‘rnini bosuvchi, 100% glyutensiz, uglevodsiz (Keto) uy krekerlari.

