UPDATE public.admin_recipes SET title_uz = COALESCE(title_uz, 'Cacao Maca Magic'), description_uz = COALESCE(description_uz, 'Ayol gormonlarini muvozanatlashtiradigan va baxt gormoni darajasini oshiradigan iliq lazzat.

Foydasi: Perudan kelib chiqqan "Maca" (maka) ildizi kukuni ayollarda gormonlarni (PMS va menopauza davrida) tartibga soladi, quvvat va libidoni oshiradi. Kakao esa magniy manbaidir.'), category_uz = COALESCE(category_uz, 'Foydali ichimliklar'), tags_uz = COALESCE(tags_uz, ARRAY['umumiy']::text[]), ingredients_uz = COALESCE(ingredients_uz, '["Shakarsiz, sof kakao kukuni: 1 osh qoshiq","Maca (maka) kukuni: 1 choy qoshiq","Bodom yoki funduk suti: 1 stakan","Dolchin va asal."]'::jsonb), instructions_uz = COALESCE(instructions_uz, '["Barcha masalliqlarni kichik qozonda isitib, yaxshilab (ko‘pik hosil bo‘lguncha) ko‘pirtiring. Issiq shokolad kabi, kechki payt zavq bilan iching."]'::jsonb) WHERE id = '9af7ce60-d92c-4cdf-bbaf-e2276dc4e407';
UPDATE public.admin_recipes SET title_uz = COALESCE(title_uz, 'No‘xatli blondi'), description_uz = COALESCE(description_uz, 'Tarkibida no‘xat borligiga hech kim ishonmaydigan karamelli, unsiz keks.

Foydasi: Bu shirinlik sof oqsil va murakkab uglevodlar manbaidir. Glyuten sababli qorin dam bo‘lishiga olib kelmaydi, kechki mashg‘ulotdan so‘ng (mushaklar tiklanishi uchun) choy bilan juda yaxshi ketadi.'), category_uz = COALESCE(category_uz, 'Sog‘lom shirinliklar'), tags_uz = COALESCE(tags_uz, ARRAY['general']::text[]), ingredients_uz = COALESCE(ingredients_uz, '["Konservalangan no‘xat: 1 stakan (yaxshilab yuvilgan va po‘sti archilgan)","Yeryong‘oq pastasi: 3 osh qoshiq","Asal yoki zarang siropi: 3 osh qoshiq","Vanilin, qabartma.","Shokolad tomchilari (qora shokoladli)."]'::jsonb), instructions_uz = COALESCE(instructions_uz, '["Shokoladdan tashqari barcha masalliqlarni blenderda butunlay bir xil, silliq xamir holiga kelguncha aralashtiring. Unga shokolad tomchilarini qo‘shib, kichik kvadrat keks qolipiga quying. 175 darajada 20 daqiqa pishiring. Iliqligida bo‘laklarga bo‘ling."]'::jsonb) WHERE id = '4b5bc08b-15b1-4187-aa19-05b7b3bb4ae4';

